1	{
2	  "name": "stockroom",
3	  "version": "0.0.0",
4	  "private": true,
5	  "type": "module",
6	  "engines": {
7	    "node": ">=24 <25"
8	  },
9	  "scripts": {
10	    "start": "node app.ts"
11	  },
12	  "bin": {
13	    "stockroom": "app.ts"
14	  }
15	}
16

1	#!/usr/bin/env node
2	// stockroom —— 本地多仓库存台账（Node.js 24，TypeScript，无外部运行依赖）
3	
4	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
5	import { join } from 'node:path';
6	
7	const APP_NAME = 'stockroom';
8	const DATA_FILENAME = 'stockroom.json';
9	const DEFAULT_DATA_DIR = '.stockroom';
10	
11	class UsageError extends Error {} // 命令行用法错误 -> 退出码 2
12	class BizError extends Error {} // 业务拒绝 -> 退出码 1
13	class DataError extends Error {} // 数据读取/保存失败 -> 退出码 1
14	
15	type DocType = 'in' | 'out' | 'transfer';
16	type EntryType =
17	  | DocType
18	  | 'count'
19	  | 'arrival'
20	  | 'return'
21	  | 'in-rev'
22	  | 'out-rev'
23	  | 'transfer-rev'
24	  | 'count-rev'
25	  | 'arrival-rev'
26	  | 'return-rev';
27	
28	interface LedgerEntry {
29	  seq: number; // 全局流水序号，即提交顺序
30	  doc: string; // 单据编号（冲销流水此处为冲销单编号）
31	  type: EntryType;
32	  product: string;
33	  wh: string; // 本流水条目变动余量的仓库（到货为采购单收货仓）
34	  qty?: number; // 入库/出库/调拨/到货类流水：恒为正数，方向由类型 / 出入仓决定；盘点类流水不用此字段
35	  before: number;
36	  after: number;
37	  from?: string; // 调拨（或冲销调拨）的调出仓
38	  to?: string; // 调拨（或冲销调拨）的调入仓
39	  po?: string; // 到货/退货流水：所属采购单编号
40	  arr?: string; // 退货（及冲销退货）流水：原到货单编号
41	  orig?: string; // 冲销流水：被冲销的原单编号
42	  expected?: number; // 盘点（及冲销盘点）流水：预期账面量
43	  actual?: number; // 盘点（及冲销盘点）流水：实盘量
44	  diff?: number; // 盘点差额 = 实盘 - 账面（可正、可负、可零）；冲销盘点流水记录原差额
45	}
46	
47	interface DocRecord {
48	  content: Record<string, unknown>; // 规范化业务内容（明细顺序无关）
49	  resultLines: string[]; // 原提交结果，供幂等重放
50	}
51	
52	interface ReversalRecord {
53	  orig: string; // 被冲销的原单编号
54	  resultLines: string[]; // 冲销提交结果，供幂等重放
55	}
56	
57	interface PurchaseRecord {
58	  poId: string;
59	  supplier: string;
60	  wh: string; // 收货仓
61	  ordered: Record<string, number>; // 商品 -> 订购量（合并后，正安全整数）
62	  resultLines: string[]; // 登记结果，供幂等重放
63	}
64	
65	interface ArrivalRecord {
66	  poId: string; // 所属采购单
67	  wh: string; // 采购单收货仓（冗余自采购单，便于校验与展示）
68	  qty: Record<string, number>; // 本次到货：商品 -> 数量（合并后，正安全整数）
69	  resultLines: string[]; // 到货提交结果，供幂等重放
70	}
71	
72	interface CancelRecord {
73	  poId: string; // 所属采购单
74	  qty: Record<string, number>; // 本次取消：商品 -> 数量（合并后，正安全整数）
75	  resultLines: string[]; // 取消提交结果，供幂等重放
76	}
77	
78	interface ReturnRecord {
79	  arrId: string; // 原到货单编号
80	  poId: string; // 所属采购单（冗余自原到货单，便于校验与展示）
81	  wh: string; // 原到货单收货仓（退货从该仓当前余量扣减）
82	  qty: Record<string, number>; // 本次退货：商品 -> 数量（合并后，正安全整数）
83	  resultLines: string[]; // 退货提交结果，供幂等重放
84	}
85	
86	interface ReplenishRule {
87	  min: number; // 下限：预计量不高于此值才触发补货（非负安全整数）
88	  target: number; // 目标：补货缺口 = 目标 - 预计量（非负安全整数，恒大于下限）
89	}
90	
91	interface PlanTransfer {
92	  docId: string; // 调拨子单编号（与库存单据共用编号空间，执行时才占用）
93	  product: string;
94	  from: string; // 调出仓
95	  to: string; // 调入仓（缺货仓）
96	  qty: number; // 冻结的调拨数量（正安全整数）
97	}
98	
99	interface PlanPurchase {
100	  poId: string; // 采购子单编号（独立采购编号空间，执行时才占用）
101	  supplier: string;
102	  wh: string; // 收货仓（缺货仓）
103	  product: string;
104	  qty: number; // 冻结的采购数量（正安全整数）
105	}
106	
107	interface PlanSnapshot {
108	  // 涉及商品（出现在任一调拨/采购子单中的商品）在保存时的全部补货规则
109	  rules: Record<string, Record<string, ReplenishRule>>;
110	  // 这些商品各配置仓在保存时的实存
111	  stock: Record<string, Record<string, number>>;
112	  // 这些商品各配置仓在保存时的待到货合计（精确整数十进制字符串，可超安全整数范围）
113	  pending: Record<string, Record<string, string>>;
114	}
115	
116	interface PlanRecord {
117	  planId: string;
118	  transfers: PlanTransfer[]; // 冻结的调拨子单（按建议顺序：商品、缺货仓、来源仓升序）
119	  purchases: PlanPurchase[]; // 冻结的采购子单（按商品、收货仓升序；零采购不建单）
120	  snapshot: PlanSnapshot; // 保存时冻结的核对快照
121	  status: 'pending' | 'executed';
122	  execResultLines?: string[]; // 已执行方案的落单结果原文，供重放（不再核对、不再生效）
123	}
124	
125	interface Store {
126	  version: 1;
127	  products: Record<string, string>; // 编号 -> 名称（编号区分大小写；null 原型，防特殊键串改）
128	  stock: Record<string, Record<string, number>>; // 商品 -> 仓库 -> 余量
129	  entries: LedgerEntry[];
130	  docs: Record<string, DocRecord>; // 入库/出库/调拨/盘点单去重与结果
131	  reversals: Record<string, ReversalRecord>; // 冲销单去重与结果（可冲销到货单、取消单、退货单）
132	  purchases: Record<string, PurchaseRecord>; // 采购单登记（独立编号空间，不改库存）
133	  arrivals: Record<string, ArrivalRecord>; // 到货单去重与结果（与库存单共用编号空间）
134	  cancels: Record<string, CancelRecord>; // 取消单去重与结果（与库存单共用编号空间，不改库存与流水）
135	  returns: Record<string, ReturnRecord>; // 退货单去重与结果（与库存单共用编号空间）
136	  rules: Record<string, Record<string, ReplenishRule>>; // 补货规则：商品 -> 仓库 -> 下限/目标（每组合唯一）
137	  plans: Record<string, PlanRecord>; // 补货方案（独立编号空间；保存不改库存/采购/流水）
138	}
139	
140	const REV_ENTRY_TYPES = new Set<EntryType>([
141	  'in-rev', 'out-rev', 'transfer-rev', 'count-rev', 'arrival-rev', 'return-rev',
142	]);
143	
144	function nullProto<T extends object>(): T {
145	  return Object.create(null) as T;
146	}
147	
148	function emptyStore(): Store {
149	  return {
150	    version: 1,
151	    products: nullProto(),
152	    stock: nullProto(),
153	    entries: [],
154	    docs: nullProto(),
155	    reversals: nullProto(),
156	    purchases: nullProto(),
157	    arrivals: nullProto(),
158	    cancels: nullProto(),
159	    returns: nullProto(),
160	    rules: nullProto(),
161	    plans: nullProto(),
162	  };
163	}
164	
165	// ---------- 工具 ----------
166	
167	function isPlainObject(v: unknown): v is Record<string, unknown> {
168	  return typeof v === 'object' && v !== null && !Array.isArray(v);
169	}
170	
171	function isNonNegSafeInt(v: unknown): v is number {
172	  return typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
173	}
174	
175	function isPosSafeInt(v: unknown): v is number {
176	  return typeof v === 'number' && Number.isSafeInteger(v) && v > 0;
177	}
178	
179	function trimOrThrow(label: string, raw: string): string {
180	  const s = raw.trim();
181	  if (s === '') throw new BizError(`${label}去除首尾空白后不能为空`);
182	  return s;
183	}
184	
185	/** 规范化序列化：对象键排序，保证业务内容比较与明细顺序无关。 */
186	function stableStringify(v: unknown): string {
187	  if (isPlainObject(v)) {
188	    return (
189	      '{' +
190	      Object.keys(v)
191	        .sort()
192	        .map((k) => JSON.stringify(k) + ':' + stableStringify(v[k]))
193	        .join(',') +
194	      '}'
195	    );
196	  }
197	  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
198	  return JSON.stringify(v);
199	}
200	
201	// ---------- 数据持久化 ----------
202	
203	function dataPath(dataDir: string): string {
204	  return join(dataDir, DATA_FILENAME);
205	}
206	
207	function loadStore(dataDir: string): Store {
208	  let raw: string;
209	  try {
210	    raw = readFileSync(dataPath(dataDir), 'utf8');
211	  } catch (e) {
212	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore(); // 尚不存在 -> 空库
213	    throw new DataError(`无法读取数据文件 ${dataPath(dataDir)}：${(e as Error).message}`);
214	  }
215	
216	  let data: unknown;
217	  try {
218	    // JSON.parse 将 "__proto__" 保留为普通自有属性（不设置原型）；随后 validateStore
219	    // 会把全部容器重新装入 null 原型对象，constructor 等特殊键同样安全。
220	    data = JSON.parse(raw);
221	  } catch {
222	    throw new DataError(`数据文件已损坏，无法解析 JSON：${dataPath(dataDir)}（不会作为空库覆盖）`);
223	  }
224	  return validateStore(data);
225	}
226	
227	function validateStore(data: unknown): Store {
228	  const bad = (msg: string): DataError =>
229	    new DataError(`数据文件已损坏或格式不正确（${msg}），拒绝启动以免覆盖原数据`);
230	
231	  if (!isPlainObject(data)) throw bad('根节点不是对象');
232	  if (data.version !== 1) throw bad(`不支持的数据版本：${String(data.version)}`);
233	
234	  // 重新装入 null 原型容器：即使磁盘数据来自普通对象，constructor/__proto__ 等键也安全
235	  const store = emptyStore();
236	
237	  if (!isPlainObject(data.products)) throw bad('products 不是对象');
238	  for (const [id, name] of Object.entries(data.products)) {
239	    if (typeof id !== 'string' || id.trim() === '' || typeof name !== 'string')
240	      throw bad('products 中存在非法编号或名称');
241	    store.products[id] = name;
242	  }
243	
244	  if (!isPlainObject(data.stock)) throw bad('stock 不是对象');
245	  for (const [pid, whs] of Object.entries(data.stock)) {
246	    if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的库存不是对象`);
247	    const whMap = nullProto<Record<string, number>>();
248	    for (const [wh, qty] of Object.entries(whs)) {
249	      if (typeof wh !== 'string' || wh.trim() === '' || !isNonNegSafeInt(qty))
250	        throw bad(`商品 ${pid} 仓库 ${String(wh)} 的余量非法`);
251	      whMap[wh] = qty;
252	    }
253	    store.stock[pid] = whMap;
254	  }
255	
256	  if (!Array.isArray(data.entries)) throw bad('entries 不是数组');
257	  let lastSeq = 0;
258	  for (const e of data.entries as unknown[]) {
259	    if (!isPlainObject(e)) throw bad('存在非法流水条目');
260	    if (!isPosSafeInt(e.seq) || e.seq !== ++lastSeq) throw bad('流水序号不连续');
261	    if (typeof e.doc !== 'string' || e.doc.trim() === '') throw bad('流水缺少单据编号');
262	    const isRev = REV_ENTRY_TYPES.has(e.type as EntryType);
263	    const isOrig =
264	      e.type === 'in' || e.type === 'out' || e.type === 'transfer' || e.type === 'count' ||
265	      e.type === 'arrival' || e.type === 'return';
266	    if (!isRev && !isOrig) throw bad('流水类型非法');
267	    if (typeof e.product !== 'string' || e.product.trim() === '') throw bad('流水缺少商品编号');
268	    if (typeof e.wh !== 'string' || e.wh.trim() === '') throw bad('流水缺少仓库标识');
269	    if (!isNonNegSafeInt(e.before) || !isNonNegSafeInt(e.after)) throw bad('流水余量非法');
270	    if (e.type === 'count' || e.type === 'count-rev') {
271	      if (!isNonNegSafeInt(e.expected) || !isNonNegSafeInt(e.actual))
272	        throw bad('盘点流水账面/实盘量非法');
273	      if (typeof e.diff !== 'number' || !Number.isSafeInteger(e.diff)) throw bad('盘点流水差额非法');
274	      if (e.diff !== e.actual - e.expected) throw bad('盘点流水差额与账面、实盘量不一致');
275	      const applied = e.type === 'count' ? e.diff : -e.diff; // 冲销盘点应用反向差额
276	      if (e.after - e.before !== applied) throw bad('盘点流水差额与前后余量不一致');
277	      if (e.qty !== undefined || e.from !== undefined || e.to !== undefined || e.po !== undefined ||
278	          e.arr !== undefined)
279	        throw bad('盘点流水不应携带数量、调拨、采购或退货字段');
280	    } else {
281	      if (!isPosSafeInt(e.qty)) throw bad('流水数量非法');
282	      if (e.expected !== undefined || e.actual !== undefined || e.diff !== undefined)
283	        throw bad('非盘点流水不应携带盘点字段');
284	      const delta = e.after - e.before;
285	      if (e.type === 'transfer' || e.type === 'transfer-rev') {
286	        if (typeof e.from !== 'string' || e.from.trim() === '' || typeof e.to !== 'string' || e.to.trim() === '')
287	          throw bad('调拨流水缺少调出/调入仓');
288	        if (e.po !== undefined || e.arr !== undefined) throw bad('调拨流水不应携带采购或退货字段');
289	        // 调拨：调入仓增加；冲销调拨：原调入仓扣回、原调出仓补回
290	        const expect = (e.wh === e.to) === (e.type === 'transfer') ? e.qty : -e.qty;
291	        if (delta !== expect) throw bad('流水差额与前后余量不一致');
292	      } else {
293	        if (e.from !== undefined || e.to !== undefined) throw bad('非调拨流水不应携带调拨字段');
294	        // 到货入收货仓、冲销退货补回为增；退货从收货仓扣减、冲销到货扣回为减
295	        const increases =
296	          e.type === 'in' || e.type === 'out-rev' || e.type === 'arrival' || e.type === 'return-rev';
297	        if (delta !== (increases ? e.qty : -e.qty)) throw bad('流水差额与前后余量不一致');
298	        if (e.type === 'arrival' || e.type === 'arrival-rev') {
299	          if (typeof e.po !== 'string' || e.po.trim() === '') throw bad('到货流水缺少采购单编号');
300	          if (e.arr !== undefined) throw bad('到货流水不应携带原到货单字段');
301	        } else if (e.type === 'return' || e.type === 'return-rev') {
302	          if (typeof e.po !== 'string' || e.po.trim() === '') throw bad('退货流水缺少采购单编号');
303	          if (typeof e.arr !== 'string' || e.arr.trim() === '') throw bad('退货流水缺少原到货单编号');
304	        } else if (e.po !== undefined || e.arr !== undefined) {
305	          throw bad('非到货/退货流水不应携带采购或退货字段');
306	        }
307	      }
308	    }
309	    if (isRev) {
310	      if (typeof e.orig !== 'string' || e.orig.trim() === '') throw bad('冲销流水缺少原单编号');
311	    } else if (e.orig !== undefined) {
312	      throw bad('原始单据流水不应携带冲销标记');
313	    }
314	    store.entries.push(e as unknown as LedgerEntry);
315	  }
316	
317	  if (!isPlainObject(data.docs)) throw bad('docs 不是对象');
318	  for (const [docId, rec] of Object.entries(data.docs)) {
319	    if (typeof docId !== 'string' || docId.trim() === '') throw bad('存在非法单据编号');
320	    if (!isPlainObject(rec) || !isPlainObject(rec.content) || !Array.isArray(rec.resultLines))
321	      throw bad(`单据 ${docId} 的去重记录非法`);
322	    if (!rec.resultLines.every((l) => typeof l === 'string')) throw bad(`单据 ${docId} 的结果记录非法`);
323	    const c = rec.content;
324	    if (c.type !== 'in' && c.type !== 'out' && c.type !== 'transfer' && c.type !== 'count')
325	      throw bad(`单据 ${docId} 的业务类型非法`);
326	    if (!isPlainObject(c.items)) throw bad(`单据 ${docId} 的明细非法`);
327	    for (const [pid, item] of Object.entries(c.items)) {
328	      if (pid.trim() === '') throw bad(`单据 ${docId} 存在非法明细`);
329	      if (c.type === 'count') {
330	        if (!isPlainObject(item) || !isNonNegSafeInt(item.expected) || !isNonNegSafeInt(item.actual))
331	          throw bad(`单据 ${docId} 存在非法盘点明细`);
332	      } else if (!isPosSafeInt(item)) {
333	        throw bad(`单据 ${docId} 存在非法明细`);
334	      }
335	    }
336	    if (c.type === 'transfer') {
337	      if (typeof c.from !== 'string' || c.from.trim() === '' || typeof c.to !== 'string' || c.to.trim() === '')
338	        throw bad(`单据 ${docId} 的调拨仓非法`);
339	    } else if (typeof c.wh !== 'string' || c.wh.trim() === '') {
340	      throw bad(`单据 ${docId} 的仓库非法`);
341	    }
342	    store.docs[docId] = rec as unknown as DocRecord;
343	  }
344	
345	  // purchases 为新增字段：合法旧数据没有该字段，按空集合处理。
346	  // 采购单编号独立于库存单据编号空间，允许与入库/到货/冲销单同名。
347	  if (data.purchases !== undefined) {
348	    if (!isPlainObject(data.purchases)) throw bad('purchases 不是对象');
349	    for (const [poId, rec] of Object.entries(data.purchases)) {
350	      if (typeof poId !== 'string' || poId.trim() === '') throw bad('存在非法采购单编号');
351	      if (
352	        !isPlainObject(rec) ||
353	        typeof rec.supplier !== 'string' || rec.supplier.trim() === '' ||
354	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
355	        !isPlainObject(rec.ordered) ||
356	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
357	      )
358	        throw bad(`采购单 ${poId} 的记录非法`);
359	      if (rec.poId !== undefined && rec.poId !== poId) throw bad(`采购单 ${poId} 的内嵌编号不一致`);
360	      const ordered = nullProto<Record<string, number>>();
361	      for (const [pid, qty] of Object.entries(rec.ordered)) {
362	        if (pid.trim() === '' || !isPosSafeInt(qty)) throw bad(`采购单 ${poId} 存在非法订购明细`);
363	        ordered[pid] = qty;
364	      }
365	      if (Object.keys(ordered).length === 0) throw bad(`采购单 ${poId} 至少需要一种商品`);
366	      store.purchases[poId] = {
367	        poId, supplier: rec.supplier, wh: rec.wh, ordered, resultLines: rec.resultLines,
368	      };
369	    }
370	  }
371	
372	  // arrivals 为新增字段：合法旧数据没有该字段，按空集合处理。
373	  // 到货单与入库/出库/调拨/盘点/冲销单共用全局唯一编号空间。
374	  if (data.arrivals !== undefined) {
375	    if (!isPlainObject(data.arrivals)) throw bad('arrivals 不是对象');
376	    for (const [arrId, rec] of Object.entries(data.arrivals)) {
377	      if (typeof arrId !== 'string' || arrId.trim() === '') throw bad('存在非法到货单编号');
378	      if (store.docs[arrId] !== undefined) throw bad(`到货单编号 ${arrId} 与原始库存单据编号冲突`);
379	      if (
380	        !isPlainObject(rec) ||
381	        typeof rec.poId !== 'string' || rec.poId.trim() === '' ||
382	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
383	        !isPlainObject(rec.qty) ||
