676	        cancelled[pid] = (cancelled[pid] ?? 0n) + BigInt(q);
677	        if ((arrived[pid] ?? 0n) + cancelled[pid] > BigInt(po.ordered[pid]))
678	          throw bad(`采购单 ${poId} 商品 ${pid} 有效到货与有效取消合计超过订购量（待到货量为负）`);
679	      }
680	    }
681	  }
682	
683	  // rules 为新增字段：合法旧数据没有该字段，按无规则处理。
684	  // 规则按（商品, 仓库）唯一存放；商品必须已登记，仓库无需登记；
685	  // 下限与目标均为非负安全整数且下限小于目标，非法规则视为损坏数据，拒绝读取与覆盖。
686	  if (data.rules !== undefined) {
687	    if (!isPlainObject(data.rules)) throw bad('rules 不是对象');
688	    for (const [pid, whs] of Object.entries(data.rules)) {
689	      if (typeof pid !== 'string' || pid.trim() === '') throw bad('rules 中存在非法商品编号');
690	      if (store.products[pid] === undefined) throw bad(`补货规则指向未登记商品 ${pid}`);
691	      if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的补货规则不是对象`);
692	      const whMap = nullProto<Record<string, ReplenishRule>>();
693	      for (const [wh, rule] of Object.entries(whs)) {
694	        if (typeof wh !== 'string' || wh.trim() === '')
695	          throw bad(`商品 ${pid} 的补货规则存在非法仓库标识`);
696	        if (
697	          !isPlainObject(rule) ||
698	          !isNonNegSafeInt(rule.min) ||
699	          !isNonNegSafeInt(rule.target) ||
700	          rule.min >= rule.target
701	        )
702	          throw bad(`商品 ${pid} 仓库 ${wh} 的补货规则非法（下限与目标须为非负安全整数且下限小于目标）`);
703	        whMap[wh] = { min: rule.min, target: rule.target };
704	      }
705	      if (Object.keys(whMap).length === 0) throw bad(`商品 ${pid} 的补货规则为空`);
706	      store.rules[pid] = whMap;
707	    }
708	  }
709	
710	  // plans 为新增字段：合法旧数据没有该字段，按无方案处理。
711	  // 方案编号独立空间；损坏方案（结构非法、快照非法）或已执行方案的子单关联断裂
712	  // （子单不存在或内容与冻结不符）一律视为损坏数据，拒绝读取与覆盖。
713	  if (data.plans !== undefined) {
714	    if (!isPlainObject(data.plans)) throw bad('plans 不是对象');
715	    for (const [planId, rec] of Object.entries(data.plans)) {
716	      if (typeof planId !== 'string' || planId.trim() === '') throw bad('存在非法方案编号');
717	      if (!isPlainObject(rec)) throw bad(`方案 ${planId} 的记录非法`);
718	      if (rec.planId !== undefined && rec.planId !== planId) throw bad(`方案 ${planId} 的内嵌编号不一致`);
719	      if (rec.status !== 'pending' && rec.status !== 'executed') throw bad(`方案 ${planId} 的状态非法`);
720	      if (!Array.isArray(rec.transfers) || !Array.isArray(rec.purchases))
721	        throw bad(`方案 ${planId} 的子单记录非法`);
722	      if (rec.transfers.length + rec.purchases.length === 0)
723	        throw bad(`方案 ${planId} 不含任何子单`);
724	
725	      const transfers: PlanTransfer[] = [];
726	      const seenDoc = new Set<string>();
727	      for (const t of rec.transfers as unknown[]) {
728	        if (
729	          !isPlainObject(t) ||
730	          typeof t.docId !== 'string' || t.docId.trim() === '' ||
731	          typeof t.product !== 'string' || t.product.trim() === '' ||
732	          typeof t.from !== 'string' || t.from.trim() === '' ||
733	          typeof t.to !== 'string' || t.to.trim() === '' ||
734	          !isPosSafeInt(t.qty)
735	        )
736	          throw bad(`方案 ${planId} 存在非法调拨子单`);
737	        if (t.from === t.to) throw bad(`方案 ${planId} 的调拨子单 ${t.docId} 调出仓与调入仓相同`);
738	        if (seenDoc.has(t.docId)) throw bad(`方案 ${planId} 的调拨子单编号 ${t.docId} 重复`);
739	        seenDoc.add(t.docId);
740	        transfers.push({ docId: t.docId, product: t.product, from: t.from, to: t.to, qty: t.qty });
741	      }
742	
743	      const purchases: PlanPurchase[] = [];
744	      const seenPo = new Set<string>();
745	      for (const p of rec.purchases as unknown[]) {
746	        if (
747	          !isPlainObject(p) ||
748	          typeof p.poId !== 'string' || p.poId.trim() === '' ||
749	          typeof p.supplier !== 'string' || p.supplier.trim() === '' ||
750	          typeof p.wh !== 'string' || p.wh.trim() === '' ||
751	          typeof p.product !== 'string' || p.product.trim() === '' ||
752	          !isPosSafeInt(p.qty)
753	        )
754	          throw bad(`方案 ${planId} 存在非法采购子单`);
755	        if (seenPo.has(p.poId)) throw bad(`方案 ${planId} 的采购子单编号 ${p.poId} 重复`);
756	        seenPo.add(p.poId);
757	        purchases.push({ poId: p.poId, supplier: p.supplier, wh: p.wh, product: p.product, qty: p.qty });
758	      }
759	
760	      // 快照：涉及商品的全部补货规则、各配置仓实存与待到货合计（十进制字符串）
761	      if (!isPlainObject(rec.snapshot)) throw bad(`方案 ${planId} 缺少快照`);
762	      const snap = rec.snapshot;
763	      if (!isPlainObject(snap.rules) || !isPlainObject(snap.stock) || !isPlainObject(snap.pending))
764	        throw bad(`方案 ${planId} 的快照非法`);
765	      const snapRules = nullProto<Record<string, Record<string, ReplenishRule>>>();
766	      const snapStock = nullProto<Record<string, Record<string, number>>>();
767	      const snapPending = nullProto<Record<string, Record<string, string>>>();
768	      for (const [pid, whs] of Object.entries(snap.rules)) {
769	        if (typeof pid !== 'string' || pid.trim() === '') throw bad(`方案 ${planId} 快照存在非法商品编号`);
770	        if (store.products[pid] === undefined) throw bad(`方案 ${planId} 快照涉及未登记商品 ${pid}`);
771	        if (!isPlainObject(whs)) throw bad(`方案 ${planId} 快照中商品 ${pid} 的规则不是对象`);
772	        const ruleMap = nullProto<Record<string, ReplenishRule>>();
773	        for (const [wh, rule] of Object.entries(whs)) {
774	          if (typeof wh !== 'string' || wh.trim() === '') throw bad(`方案 ${planId} 快照存在非法仓库标识`);
775	          if (
776	            !isPlainObject(rule) ||
777	            !isNonNegSafeInt(rule.min) ||
778	            !isNonNegSafeInt(rule.target) ||
779	            rule.min >= rule.target
780	          )
781	            throw bad(`方案 ${planId} 快照中商品 ${pid} 仓库 ${wh} 的补货规则非法`);
782	          ruleMap[wh] = { min: rule.min, target: rule.target };
783	        }
784	        snapRules[pid] = ruleMap;
785	      }
786	      if (Object.keys(snapRules).length === 0) throw bad(`方案 ${planId} 快照不含任何商品规则`);
787	      for (const [pid, whs] of Object.entries(snap.stock)) {
788	        if (snapRules[pid] === undefined || !isPlainObject(whs))
789	          throw bad(`方案 ${planId} 快照实存与规则不一致`);
790	        const m = nullProto<Record<string, number>>();
791	        for (const [wh, qty] of Object.entries(whs)) {
792	          if (snapRules[pid][wh] === undefined || !isNonNegSafeInt(qty))
793	            throw bad(`方案 ${planId} 快照实存与规则不一致`);
794	          m[wh] = qty;
795	        }
796	        if (Object.keys(m).length !== Object.keys(snapRules[pid]).length)
797	          throw bad(`方案 ${planId} 快照实存与规则不一致`);
798	        snapStock[pid] = m;
799	      }
800	      for (const [pid, whs] of Object.entries(snap.pending)) {
801	        if (snapRules[pid] === undefined || !isPlainObject(whs))
802	          throw bad(`方案 ${planId} 快照待到货与规则不一致`);
803	        const m = nullProto<Record<string, string>>();
804	        for (const [wh, v] of Object.entries(whs)) {
805	          if (snapRules[pid][wh] === undefined || typeof v !== 'string' || !/^\d+$/.test(v))
806	            throw bad(`方案 ${planId} 快照待到货与规则不一致`);
807	          m[wh] = v;
808	        }
809	        if (Object.keys(m).length !== Object.keys(snapRules[pid]).length)
810	          throw bad(`方案 ${planId} 快照待到货与规则不一致`);
811	        snapPending[pid] = m;
812	      }
813	      if (
814	        Object.keys(snapStock).length !== Object.keys(snapRules).length ||
815	        Object.keys(snapPending).length !== Object.keys(snapRules).length
816	      )
817	        throw bad(`方案 ${planId} 快照与规则不一致`);
818	      for (const t of transfers) {
819	        if (snapRules[t.product] === undefined)
820	          throw bad(`方案 ${planId} 的调拨子单 ${t.docId} 商品 ${t.product} 不在快照规则内`);
821	      }
822	      for (const p of purchases) {
823	        if (snapRules[p.product] === undefined)
824	          throw bad(`方案 ${planId} 的采购子单 ${p.poId} 商品 ${p.product} 不在快照规则内`);
825	      }
826	
827	      // 已执行方案：子单关联必须完整且内容与冻结一致，否则视为损坏数据
828	      let execResultLines: string[] | undefined;
829	      if (rec.status === 'executed') {
830	        if (!Array.isArray(rec.execResultLines) || !rec.execResultLines.every((l) => typeof l === 'string'))
831	          throw bad(`已执行方案 ${planId} 的落单结果非法`);
832	        execResultLines = rec.execResultLines;
833	        for (const t of transfers) {
834	          const doc = store.docs[t.docId];
835	          if (doc === undefined) throw bad(`已执行方案 ${planId} 的调拨子单 ${t.docId} 不存在`);
836	          const c = doc.content;
837	          const items = c.items as Record<string, unknown>;
838	          const keys = Object.keys(items);
839	          if (
840	            c.type !== 'transfer' || c.from !== t.from || c.to !== t.to ||
841	            keys.length !== 1 || keys[0] !== t.product || items[t.product] !== t.qty
842	          )
843	            throw bad(`已执行方案 ${planId} 的调拨子单 ${t.docId} 内容与冻结方案不一致`);
844	        }
845	        for (const p of purchases) {
846	          const po = store.purchases[p.poId];
847	          if (po === undefined) throw bad(`已执行方案 ${planId} 的采购子单 ${p.poId} 不存在`);
848	          const keys = Object.keys(po.ordered);
849	          if (
850	            po.supplier !== p.supplier || po.wh !== p.wh ||
851	            keys.length !== 1 || keys[0] !== p.product || po.ordered[p.product] !== p.qty
852	          )
853	            throw bad(`已执行方案 ${planId} 的采购子单 ${p.poId} 内容与冻结方案不一致`);
854	        }
855	      } else if (rec.execResultLines !== undefined) {
856	        throw bad(`待执行方案 ${planId} 不应携带落单结果`);
857	      }
858	
859	      store.plans[planId] = {
860	        planId, transfers, purchases,
861	        snapshot: { rules: snapRules, stock: snapStock, pending: snapPending },
862	        status: rec.status,
863	        ...(execResultLines !== undefined ? { execResultLines } : {}),
864	      };
865	    }
866	  }
867	
868	  return store;
869	}
