883	// ---------- 参数解析 ----------
884	
885	interface ParsedArgs {
886	  positionals: string[];
887	  flags: Record<string, string>;
888	  multi: Record<string, string[]>;
889	}
890	
891	function parseArgs(
892	  tokens: string[],
893	  singles: string[],
894	  multis: string[] = [],
895	): ParsedArgs {
896	  const out: ParsedArgs = { positionals: [], flags: {}, multi: {} };
897	  const singleSet = new Set(singles);
898	  const multiSet = new Set(multis);
899	
900	  for (let i = 0; i < tokens.length; i++) {
901	    const tok = tokens[i];
902	    if (tok.startsWith('--')) {
903	      let key = tok;
904	      let value: string | undefined;
905	      const eq = tok.indexOf('=');
906	      if (eq >= 0) {
907	        key = tok.slice(0, eq);
908	        value = tok.slice(eq + 1);
909	      }
910	      if (!singleSet.has(key) && !multiSet.has(key)) throw new UsageError(`未知参数：${tok}`);
911	      if (value === undefined) {
912	        if (i + 1 >= tokens.length) throw new UsageError(`参数 ${key} 缺少取值`);
913	        value = tokens[++i];
914	      }
915	      if (multiSet.has(key)) (out.multi[key] ??= []).push(value);
916	      else if (out.flags[key] !== undefined) throw new UsageError(`参数 ${key} 重复指定`);
917	      else out.flags[key] = value;
918	    } else {
919	      out.positionals.push(tok);
920	    }
921	  }
922	  return out;
923	}
924	
925	function parseItem(raw: string, merged: Map<string, number>): void {
926	  const idx = raw.indexOf(':');
927	  if (idx <= 0) throw new BizError(`明细格式应为 “商品编号:数量”：${raw}`);
928	  const pid = trimOrThrow('商品编号', raw.slice(0, idx));
929	  const qtyRaw = raw.slice(idx + 1).trim();
930	  if (!/^\d+$/.test(qtyRaw)) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
931	  const qty = Number(qtyRaw);
932	  if (!Number.isSafeInteger(qty) || qty <= 0) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
933	  const sum = (merged.get(pid) ?? 0) + qty; // 同单同商品先合并
934	  if (!Number.isSafeInteger(sum)) throw new BizError(`商品 ${pid} 累计数量超出安全整数范围`);
935	  merged.set(pid, sum);
936	}
