1043	  const poRaw = args.positionals[0];
1044	  if (poRaw === undefined || args.positionals.length !== 1)
1045	    throw new UsageError('用法：po register <采购编号> --supplier <供应商名称> --wh <收货仓> --item <商品编号:订购量> [...]');
1046	  if (args.flags['--supplier'] === undefined) throw new UsageError('采购单必须提供 --supplier <供应商名称>');
1047	  if (args.flags['--wh'] === undefined) throw new UsageError('采购单必须提供 --wh <收货仓>');
1048	
1049	  const items = new Map<string, number>();
1050	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
1051	  if (items.size === 0) throw new UsageError('采购单至少需要一条 --item 商品编号:订购量 明细');
1052	
1053	  return {
1054	    poId: trimOrThrow('采购编号', poRaw),
1055	    supplier: trimOrThrow('供应商名称', args.flags['--supplier']),
1056	    wh: trimOrThrow('收货仓标识', args.flags['--wh']),
1057	    items,
1058	  };
