1060	
1061	function parseArrivalArgs(tokens: string[]): ArrivalRequest {
1062	  const args = parseArgs(tokens, ['--po'], ['--item']);
1063	  const arrRaw = args.positionals[0];
1064	  if (arrRaw === undefined || args.positionals.length !== 1)
1065	    throw new UsageError('用法：arrival <到货单编号> --po <采购编号> --item <商品编号:到货量> [...]');
1066	  if (args.flags['--po'] === undefined) throw new UsageError('到货必须通过 --po <采购编号> 指定所属采购单（收货仓取采购单）');
1067	
1068	  const items = new Map<string, number>();
1069	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
1070	  if (items.size === 0) throw new UsageError('到货单至少需要一条 --item 商品编号:到货量 明细');
1071	
1072	  return { arrId: trimOrThrow('到货单编号', arrRaw), poId: trimOrThrow('采购编号', args.flags['--po']), items };
1073	}
