1108	// ---------- 整批导入文件解析 ----------
1109	
1110	type ImportRequest =
1111	  | { kind: 'doc'; req: DocRequest }
1112	  | { kind: 'count'; req: CountRequest }
1113	  | { kind: 'reverse'; docId: string; orig: string }
1114	  | { kind: 'po'; req: PurchaseRequest }
1115	  | { kind: 'arrival'; req: ArrivalRequest }
1116	  | { kind: 'cancel'; req: CancelRequest }
1117	  | { kind: 'return'; req: ReturnRequest };
1118	
1119	/** 读取导入文件：无法读取属于读写失败（退出 1），不改变任何已提交状态。 */
1120	function readImportFile(file: string): string {
1121	  try {
1122	    return readFileSync(file, 'utf8');
1123	  } catch (e) {
1124	    throw new DataError(`无法读取导入文件 ${file}：${(e as Error).message}（不会改变任何已提交数据）`);
1125	  }
1126	}
1127	
1128	/**
1129	 * 解析整批导入文件。文件级结构错误（非合法 JSON、根不是数组、空列表）属于文件
1130	 * 格式错误（退出 2）；逐项格式不合法属于业务拒绝（退出 1），指出位置与原因。
1131	 */
1132	function parseImportFile(raw: string): ImportRequest[] {
1133	  let data: unknown;
1134	  try {
1135	    data = JSON.parse(raw);
1136	  } catch (e) {
1137	    throw new UsageError(`导入文件不是合法 JSON：${(e as Error).message}`);
1138	  }
1139	  if (!Array.isArray(data)) throw new UsageError('导入文件格式错误：根节点必须是单据对象组成的有序数组');
1140	  if (data.length === 0) throw new UsageError('导入文件格式错误：单据列表至少包含一项');
1141	
1142	  const out: ImportRequest[] = [];
1143	  // 顶层位置一律标注 1 起序号，便于纠正
1144	  const at = (i: number, msg: string): BizError => new BizError(`第 ${i + 1} 项：${msg}`);
1145	
1146	  const requireString = (obj: Record<string, unknown>, key: string, label: string, i: number): string => {
1147	    const v = obj[key];
1148	    if (v === undefined) throw at(i, `缺少${label}字段 "${key}"`);
1149	    if (typeof v !== 'string') throw at(i, `${label}字段 "${key}" 必须是字符串`);
1150	    const s = v.trim();
1151	    if (s === '') throw at(i, `${label}去除首尾空白后不能为空`);
1152	    return s;
1153	  };
1154	
1155	  const checkUnknown = (obj: Record<string, unknown>, allowed: readonly string[], i: number): void => {
1156	    for (const k of Object.keys(obj)) {
1157	      if (!allowed.includes(k)) throw at(i, `含不支持的字段 "${k}"（允许字段：${allowed.join('、')}）`);
1158	    }
1159	  };
1160	
1161	  const parseQtyItems = (obj: Record<string, unknown>, i: number): Map<string, number> => {
1162	    const v = obj.items;
1163	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
1164	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
1165	    if (v.length === 0) throw at(i, '商品明细至少一项');
1166	    const merged = new Map<string, number>();
1167	    v.forEach((entry, j) => {
1168	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
1169	      const e = entry as Record<string, unknown>;
1170	      checkUnknown(e, ['product', 'qty'], i);
1171	      const pid = e.product;
1172	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
1173	      const p = pid.trim();
1174	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
1175	      if (!isPosSafeInt(e.qty)) throw at(i, `商品 ${p} 的数量必须为正安全整数`);
1176	      const sum = (merged.get(p) ?? 0) + (e.qty as number); // 同单同商品先合并
1177	      if (!Number.isSafeInteger(sum)) throw at(i, `商品 ${p} 累计数量超出安全整数范围`);
1178	      merged.set(p, sum);
1179	    });
1180	    return merged;
1181	  };
1182	
1183	  const parseCountItems = (obj: Record<string, unknown>, i: number): Map<string, CountItem> => {
1184	    const v = obj.items;
1185	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
1186	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
1187	    if (v.length === 0) throw at(i, '商品明细至少一项');
1188	    const items = new Map<string, CountItem>();
1189	    v.forEach((entry, j) => {
1190	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
1191	      const e = entry as Record<string, unknown>;
1192	      checkUnknown(e, ['product', 'expected', 'actual'], i);
1193	      const pid = e.product;
1194	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
1195	      const p = pid.trim();
1196	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
1197	      if (!isNonNegSafeInt(e.expected)) throw at(i, `商品 ${p} 的预期账面量必须为非负安全整数`);
1198	      if (!isNonNegSafeInt(e.actual)) throw at(i, `商品 ${p} 的实盘量必须为非负安全整数`);
1199	      if (items.has(p)) throw at(i, `盘点明细中商品 ${p} 重复出现，拒绝提交`); // 盘点不合并
1200	      items.set(p, { expected: e.expected, actual: e.actual });
1201	    });
1202	    return items;
1203	  };
1204	
1205	  data.forEach((rawItem, i) => {
1206	    if (!isPlainObject(rawItem)) throw at(i, '不是单据对象');
1207	    const item = rawItem as Record<string, unknown>;
1208	    if (item.type === undefined) throw at(i, '缺少业务类型字段 "type"');
1209	    if (typeof item.type !== 'string') throw at(i, '业务类型字段 "type" 必须是字符串');
1210	
1211	    switch (item.type) {
1212	      case 'in':
1213	      case 'out': {
1214	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
1215	        const docId = requireString(item, 'id', '单据编号', i);
1216	        const wh = requireString(item, 'wh', '仓库标识', i);
1217	        out.push({ kind: 'doc', req: { type: item.type, docId, wh, items: parseQtyItems(item, i) } });
1218	        break;
1219	      }
1220	      case 'transfer': {
1221	        checkUnknown(item, ['type', 'id', 'from', 'to', 'items'], i);
1222	        const docId = requireString(item, 'id', '单据编号', i);
1223	        const from = requireString(item, 'from', '调出仓标识', i);
1224	        const to = requireString(item, 'to', '调入仓标识', i);
1225	        if (from === to) throw at(i, '调拨单的调出仓与调入仓不能相同');
1226	        out.push({ kind: 'doc', req: { type: 'transfer', docId, from, to, items: parseQtyItems(item, i) } });
1227	        break;
1228	      }
1229	      case 'count': {
1230	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
1231	        const docId = requireString(item, 'id', '单据编号', i);
1232	        const wh = requireString(item, 'wh', '仓库标识', i);
1233	        out.push({ kind: 'count', req: { docId, wh, items: parseCountItems(item, i) } });
1234	        break;
1235	      }
1236	      case 'reverse': {
1237	        checkUnknown(item, ['type', 'id', 'orig'], i);
1238	        const docId = requireString(item, 'id', '冲销单编号', i);
1239	        const orig = requireString(item, 'orig', '原单编号', i);
1240	        out.push({ kind: 'reverse', docId, orig });
1241	        break;
1242	      }
1243	      case 'po': {
1244	        checkUnknown(item, ['type', 'id', 'supplier', 'wh', 'items'], i);
1245	        const poId = requireString(item, 'id', '采购编号', i);
1246	        const supplier = requireString(item, 'supplier', '供应商名称', i);
1247	        const wh = requireString(item, 'wh', '收货仓标识', i);
1248	        out.push({ kind: 'po', req: { poId, supplier, wh, items: parseQtyItems(item, i) } });
1249	        break;
1250	      }
1251	      case 'arrival': {
1252	        checkUnknown(item, ['type', 'id', 'po', 'items'], i);
1253	        const arrId = requireString(item, 'id', '到货单编号', i);
1254	        const poId = requireString(item, 'po', '采购编号', i);
1255	        out.push({ kind: 'arrival', req: { arrId, poId, items: parseQtyItems(item, i) } });
1256	        break;
1257	      }
1258	      case 'cancel': {
1259	        checkUnknown(item, ['type', 'id', 'po', 'items'], i);
1260	        const canId = requireString(item, 'id', '取消单编号', i);
1261	        const poId = requireString(item, 'po', '采购编号', i);
1262	        out.push({ kind: 'cancel', req: { canId, poId, items: parseQtyItems(item, i) } });
1263	        break;
1264	      }
1265	      case 'return': {
1266	        checkUnknown(item, ['type', 'id', 'arrival', 'items'], i);
1267	        const retId = requireString(item, 'id', '退货单编号', i);
1268	        const arrId = requireString(item, 'arrival', '原到货单编号', i);
1269	        out.push({ kind: 'return', req: { retId, arrId, items: parseQtyItems(item, i) } });
1270	        break;
1271	      }
1272	      default:
1273	        throw at(i, `不支持的业务类型 "${String(item.type)}"，只允许 in、out、transfer、count、reverse、po、arrival、cancel、return`);
1274	    }
1275	  });
1276	
1277	  return out;
1278	}
