1296	function getStock(stock: Store['stock'], pid: string, wh: string): number {
1297	  return stock[pid]?.[wh] ?? 0;
1298	}
1299	
1300	function setStock(stock: Store['stock'], pid: string, wh: string, qty: number): void {
1301	  (stock[pid] ??= nullProto<Record<string, number>>())[wh] = qty;
1302	}
1303	
1304	/**
1305	 * 深拷贝余量草稿。必须自建 null 原型容器：structuredClone 不保留 null 原型，
1306	 * 普通对象在 "__proto__"/"constructor" 等商品或仓库键下会发生原型串改。
1307	 */
1308	function cloneStock(stock: Store['stock']): Store['stock'] {
1309	  const out = nullProto<Store['stock']>();
1310	  for (const pid of Object.keys(stock)) {
1311	    const whMap = nullProto<Record<string, number>>();
1312	    for (const wh of Object.keys(stock[pid])) whMap[wh] = stock[pid][wh];
1313	    out[pid] = whMap;
1314	  }
1315	  return out;
1316	}
1317	
1318	function canonicalCountContent(req: CountRequest): Record<string, unknown> {
1319	  const items: Record<string, unknown> = nullProto();
1320	  for (const pid of [...req.items.keys()].sort()) {
1321	    const it = req.items.get(pid)!;
1322	    items[pid] = { expected: it.expected, actual: it.actual };
1323	  }
1324	  return { type: 'count', wh: req.wh, items };
1325	}
1326	
1327	/** 采购单规范化内容：明细按商品编号排序，比较时与明细顺序无关。 */
1328	function canonicalPurchaseContent(req: PurchaseRequest): {
1329	  supplier: string;
1330	  wh: string;
1331	  ordered: Record<string, number>;
1332	} {
1333	  const ordered: Record<string, number> = nullProto();
1334	  for (const pid of [...req.items.keys()].sort()) ordered[pid] = req.items.get(pid)!;
1335	  return { supplier: req.supplier, wh: req.wh, ordered };
1336	}
1337	
1338	/** 到货明细规范化：合并后数量按商品编号排序。 */
1339	function canonicalArrivalItems(items: Map<string, number>): Record<string, number> {
1340	  const out: Record<string, number> = nullProto();
1341	  for (const pid of [...items.keys()].sort()) out[pid] = items.get(pid)!;
1342	  return out;
1343	}
