1352	/**
1353	 * 账务模拟器：单条命令与整批导入共用。所有变动先落在草稿余量与新增流水上，
1354	 * 编号去重视图（docs/revs）在模拟期间即时更新但不写回 base，全部项通过后由
1355	 * commit 一次性落库；模拟途中抛错则 base 与磁盘均不受影响。
1356	 */
1357	class Ledger {
1358	  private readonly base: Store;
1359	  private readonly draft: Store['stock'];
1360	  private readonly additions: LedgerEntry[] = [];
1361	  private seq: number;
1362	  private readonly docs: Record<string, DocRecord> = nullProto();
1363	  private readonly revs: Record<string, ReversalRecord> = nullProto();
1364	  private readonly pos: Record<string, PurchaseRecord> = nullProto();
1365	  private readonly arrivals: Record<string, ArrivalRecord> = nullProto();
1366	  private readonly cancels: Record<string, CancelRecord> = nullProto();
1367	  private readonly returns: Record<string, ReturnRecord> = nullProto();
1368	  private readonly reversedOrigs = new Set<string>();
1369	  private readonly newDocIds: string[] = [];
1370	  private readonly newRevIds: string[] = [];
1371	  private readonly newPoIds: string[] = [];
1372	  private readonly newArrivalIds: string[] = [];
1373	  private readonly newCancelIds: string[] = [];
1374	  private readonly newReturnIds: string[] = [];
1375	
1376	  constructor(store: Store) {
1377	    this.base = store;
1378	    this.draft = cloneStock(store.stock);
1379	    this.seq = store.entries.length;
1380	    for (const [id, rec] of Object.entries(store.docs)) this.docs[id] = rec;
1381	    for (const [id, rec] of Object.entries(store.reversals)) {
1382	      this.revs[id] = rec;
1383	      this.reversedOrigs.add(rec.orig);
1384	    }
1385	    for (const [id, rec] of Object.entries(store.purchases)) this.pos[id] = rec;
1386	    for (const [id, rec] of Object.entries(store.arrivals)) this.arrivals[id] = rec;
1387	    for (const [id, rec] of Object.entries(store.cancels)) this.cancels[id] = rec;
1388	    for (const [id, rec] of Object.entries(store.returns)) this.returns[id] = rec;
1389	  }
1390	
1391	  /** 是否有新生效单据：无新单据（全部重复）时 commit 不改写数据。 */
1392	  get changed(): boolean {
1393	    return (
1394	      this.newDocIds.length +
1395	      this.newRevIds.length +
1396	      this.newPoIds.length +
1397	      this.newArrivalIds.length +
1398	      this.newCancelIds.length +
1399	      this.newReturnIds.length > 0
1400	    );
1401	  }
1402	
1403	  /** 重建原始单据结果首行，供幂等重放。 */
1404	  private docHeader(docId: string, rec: DocRecord): string {
1405	    const c = rec.content;
1406	    const n = Object.keys(c.items as Record<string, unknown>).length;
1407	    return c.type === 'count'
1408	      ? `盘点单 ${docId} 提交成功，仓库 ${c.wh as string}，共 ${n} 种商品：`
1409	      : `${c.type === 'in' ? '入库' : c.type === 'out' ? '出库' : '调拨'}单 ${docId} 提交成功，共 ${n} 种商品：`;
1410	  }
1411	
1412	  /** 重建冲销单结果首行，供幂等重放。 */
1413	  private revHeader(revId: string, rec: ReversalRecord): string {
1414	    const origDoc = this.docs[rec.orig];
1415	    if (origDoc !== undefined) {
1416	      const type = origDoc.content.type as string;
1417	      const label = type === 'in' ? '入库' : type === 'out' ? '出库' : type === 'transfer' ? '调拨' : '盘点';
1418	      const n = Object.keys(origDoc.content.items as Record<string, unknown>).length;
1419	      return `冲销单 ${revId} 提交成功，冲销${label}原单 ${rec.orig}，共 ${n} 种商品：`;
1420	    }
1421	    const origCan = this.cancels[rec.orig];
1422	    if (origCan !== undefined) {
1423	      const n = Object.keys(origCan.qty).length;
1424	      return `冲销单 ${revId} 提交成功，冲销取消原单 ${rec.orig}（采购单 ${origCan.poId}），共 ${n} 种商品：`;
1425	    }
1426	    const origRet = this.returns[rec.orig];
1427	    if (origRet !== undefined) {
1428	      const n = Object.keys(origRet.qty).length;
1429	      return `冲销单 ${revId} 提交成功，冲销退货原单 ${rec.orig}（原到货单 ${origRet.arrId}，采购单 ${origRet.poId}），共 ${n} 种商品：`;
1430	    }
1431	    // 原单为到货单（能进入去重视图的冲销单必然指向存在的原单）
1432	    const arr = this.arrivals[rec.orig];
1433	    const n = Object.keys(arr.qty).length;
1434	    return `冲销单 ${revId} 提交成功，冲销到货原单 ${rec.orig}（采购单 ${arr.poId}），共 ${n} 种商品：`;
1435	  }
1436	
1437	  private repeatedPoSource(poId: string): 'store' | 'batch' {
1438	    return this.base.purchases[poId] !== undefined ? 'store' : 'batch';
1439	  }
1440	
1441	  private repeatedArrivalSource(arrId: string): 'store' | 'batch' {
1442	    return this.base.arrivals[arrId] !== undefined ? 'store' : 'batch';
1443	  }
1444	
1445	  /**
1446	   * 计算某采购单各商品当前“有效到货”：未冲销累计到货 - 未冲销累计退货。
1447	   * 累计总量可超过安全整数范围（反复退货、补收），必须用 BigInt 精确累计，
1448	   * 不得因中间累计舍入而改变净量；单票数量本身仍为正安全整数。
1449	   */
1450	  private effectiveArrived(poId: string): Record<string, bigint> {
1451	    const arrived = nullProto<Record<string, bigint>>();
1452	    for (const [arrId, arr] of Object.entries(this.arrivals)) {
1453	      if (arr.poId !== poId || this.reversedOrigs.has(arrId)) continue;
