2486	/**
2487	 * 计算采购单各商品的有效到货（未冲销到货-未冲销退货）、有效退货、有效取消与待到货量。
2488	 * 累计总量可超过安全整数范围（反复退货、补收），一律用 BigInt 精确累计，
2489	 * 合计与记录枚举顺序无关；有效退货合计即使超过安全整数范围也能完整显示。
2490	 */
2491	function purchaseProgress(store: Store, poId: string): {
2492	  effective: Record<string, bigint>;
2493	  returned: Record<string, bigint>;
2494	  cancelled: Record<string, bigint>;
2495	  remaining: Record<string, bigint>;
2496	} {
2497	  const effective = nullProto<Record<string, bigint>>();
2498	  for (const [arrId, arr] of Object.entries(store.arrivals)) {
2499	    if (arr.poId !== poId) continue;
2500	    const isReversed = Object.values(store.reversals).some((r) => r.orig === arrId);
2501	    if (isReversed) continue;
2502	    for (const [pid, q] of Object.entries(arr.qty)) effective[pid] = (effective[pid] ?? 0n) + BigInt(q);
2503	  }
2504	  const returned = nullProto<Record<string, bigint>>();
2505	  for (const [retId, ret] of Object.entries(store.returns)) {
2506	    if (ret.poId !== poId) continue;
2507	    const isReversed = Object.values(store.reversals).some((r) => r.orig === retId);
2508	    if (isReversed) continue;
2509	    for (const [pid, q] of Object.entries(ret.qty)) {
2510	      returned[pid] = (returned[pid] ?? 0n) + BigInt(q);
2511	      effective[pid] = (effective[pid] ?? 0n) - BigInt(q); // 未冲销退货抵减有效到货
2512	    }
2513	  }
2514	  const cancelled = nullProto<Record<string, bigint>>();
2515	  for (const [canId, can] of Object.entries(store.cancels)) {
2516	    if (can.poId !== poId) continue;
2517	    const isReversed = Object.values(store.reversals).some((r) => r.orig === canId);
2518	    if (isReversed) continue;
2519	    for (const [pid, q] of Object.entries(can.qty)) cancelled[pid] = (cancelled[pid] ?? 0n) + BigInt(q);
2520	  }
2521	  const po = store.purchases[poId];
2522	  const remaining = nullProto<Record<string, bigint>>();
2523	  for (const [pid, ordered] of Object.entries(po.ordered)) {
2524	    remaining[pid] = BigInt(ordered) - (effective[pid] ?? 0n) - (cancelled[pid] ?? 0n);
2525	  }
2526	  return { effective, returned, cancelled, remaining };
2527	}
