2529	/**
2530	 * 单商品采购状态。无取消时保持原有展示（未到货/部分到货/收齐）；
2531	 * 有取消时区分仍待收与已结清：待到货为零但含取消的结清不报“收齐”，
2532	 * 取消永远不计作到货。进度量以 BigInt 精确比较。
2533	 */
2534	function poStatus(ordered: number, effective: bigint, cancelled = 0n): string {
2535	  const remaining = BigInt(ordered) - effective - cancelled;
2536	  if (cancelled === 0n) {
2537	    if (effective === 0n) return '未到货';
2538	    if (remaining > 0n) return '部分到货';
2539	    return '收齐';
2540	  }
2541	  if (remaining > 0n) return effective === 0n ? '未到货（仍待收）' : '部分到货（仍待收）';
2542	  return effective === BigInt(ordered) ? '收齐' : '已结清（含取消）';
2543	}
