2786	interface ReplenishSuggestion {
2787	  pid: string;
2788	  wh: string;
2789	  min: number;
2790	  target: number;
2791	  onHand: number; // 本仓实存（非负安全整数）
2792	  pending: bigint; // 本仓待到货合计（精确整数，可超安全整数范围）
2793	  projected: bigint; // 预计量 = 实存 + 待到货合计
2794	  triggered: boolean; // 预计量不高于下限才触发
2795	  gap: bigint; // 缺口 = 目标 - 预计量（仅触发时为正）
2796	  transfers: { from: string; qty: bigint }[]; // 各调拨来源及数量（来源仓升序）
2797	  transferTotal: bigint; // 调拨合计
2798	  purchase: bigint; // 采购量 = 调拨后剩余缺口（可为零）
2799	}
