3002	/**
3003	 * 保存补货方案：按当前补货建议的触发、来源分配与采购数量冻结完整方案，
3004	 * 用户只为每条调拨与每个正采购缺口指定子单编号（采购项同时指定供应商），不能改量；
3005	 * 零采购不建采购子单，无触发建议拒绝保存。保存只登记方案与快照，
3006	 * 不改库存、采购与流水，也不占用任何子单编号。
3007	 * 同号同输入重放返回原方案（不重新计算）；同号改输入拒绝。
3008	 */
3009	function runPlanSave(tokens: string[], dataDir: string, store: Store): void {
3010	  const spec = parsePlanSaveArgs(tokens);
3011	  const specKey = canonicalPlanSpec(spec);
3012	
3013	  const existed = store.plans[spec.planId];
3014	  if (existed !== undefined) {
3015	    if (canonicalPlanSpecOf(existed) !== specKey)
3016	      throw new BizError(`方案编号 ${spec.planId} 已存在且保存输入不同，拒绝保存（不重新计算、不覆盖原方案）`);
3017	    console.log(`补货方案 ${spec.planId} 为重复保存，保存输入与原方案一致，返回原方案（不重新计算）：`);
3018	    printPlan(existed);
3019	    return;
3020	  }
3021	
3022	  // 当前补货建议：触发组合的调拨分配与正采购缺口即方案必须覆盖的全部内容
3023	  const combos = computeReplenish(store);
3024	  const needTransfer = new Map<string, { product: string; from: string; to: string; qty: bigint }>();
3025	  const needPurchase = new Map<string, { product: string; wh: string; qty: bigint }>();
3026	  for (const c of combos) {
3027	    if (!c.triggered) continue;
3028	    for (const t of c.transfers)
3029	      needTransfer.set(`${c.pid}\0${t.from}\0${c.wh}`, { product: c.pid, from: t.from, to: c.wh, qty: t.qty });
3030	    if (c.purchase > 0n) needPurchase.set(`${c.pid}\0${c.wh}`, { product: c.pid, wh: c.wh, qty: c.purchase });
3031	  }
3032	  if (needTransfer.size === 0 && needPurchase.size === 0)
3033	    throw new BizError('当前无补货建议（无触发组合），拒绝保存方案');
3034	
3035	  const specTransfer = new Map(spec.transfers.map((t) => [`${t.product}\0${t.from}\0${t.to}`, t.docId]));
3036	  const specPurchase = new Map(spec.purchases.map((p) => [`${p.product}\0${p.wh}`, p]));
3037	  const problems: string[] = [];
3038	  for (const key of needTransfer.keys()) {
3039	    if (!specTransfer.has(key)) problems.push(`缺少调拨子单指定：${key}`);
3040	  }
3041	  for (const key of needPurchase.keys()) {
3042	    if (!specPurchase.has(key)) problems.push(`缺少采购子单指定：${key}`);
3043	  }
3044	  for (const key of specTransfer.keys()) {
3045	    if (!needTransfer.has(key)) problems.push(`调拨子单指定与当前建议不符：${key}`);
3046	  }
3047	  for (const key of specPurchase.keys()) {
3048	    if (!needPurchase.has(key)) problems.push(`采购子单指定与当前建议不符（不存在该正采购缺口）：${key}`);
3049	  }
3050	  if (problems.length > 0)
