function verifyLedgerConsistency(store: Store): void {
  // 1. 余量连续性 + 末笔与实存一致
  const lastAfter = nullProto<Record<string, Record<string, { after: number; seq: number }>>>();
  for (const e of store.entries) {
    const prev = lastAfter[e.product]?.[e.wh];
    const expectBefore = prev === undefined ? 0 : prev.after;
    if (e.before !== expectBefore)
      throw new DataError(`数据一致性核对失败：商品 ${e.product} 仓库 ${e.wh} 第 #${e.seq} 条流水（单据 ${e.doc}）变动前余量 ${e.before} 与前一条余量 ${expectBefore} 不连续，拒绝输出报表`);
    (lastAfter[e.product] ??= nullProto())[e.wh] = { after: e.after, seq: e.seq };
  }
  // 末笔与实存
  const combos = new Set<string>();
  for (const pid of Object.keys(lastAfter)) for (const wh of Object.keys(lastAfter[pid])) combos.add(pid+'\0'+wh);
  for (const pid of Object.keys(store.stock)) for (const wh of Object.keys(store.stock[pid])) combos.add(...);
  for key: replayed = lastAfter[pid]?.[wh]?.after ?? 0; actual = getStock(store.stock, pid, wh); if (replayed !== actual) throw DataError(...末笔余量 X 与当前实存 Y 不一致...);

  // 2. 调拨两端完整性
  // 按 (doc, product, from, to) 分组，调出端与调入端数量多重集匹配
  const legs = new Map<string, { out: number[]; in: number[] }>();
  for (const e of store.entries) {
    if (e.type !== 'transfer' && e.type !== 'transfer-rev') continue;
    const key = [e.type, e.doc, e.product, e.from, e.to].join('\0');
    const g = legs.get(key) ?? { out: [], in: [] };
    // 调出端：wh === from 且减少；调入端：wh === to
    if (e.wh === e.from) g.out.push(e.qty!); else if (e.wh === e.to) g.in.push(e.qty!);
    else throw DataError(...调拨流水仓库与调出/调入仓不符...);
    legs.set(key, g);
  }
  for (const [key, g] of legs) {
    if (g.out.length !== g.in.length) throw DataError(...两端不完整...);
    sort both and compare qtys.
  }
}
```

