/** 出报表前核对完整库存流水：余量连续性、调拨两端完整性、末笔余量与当前实存一致。 */
function verifyLedgerConsistency(store: Store): void {
  const lastAfter = nullProto<Record<string, Record<string, number>>>();
  for (const e of store.entries) {
    const prev = lastAfter[e.product]?.[e.wh];
    const expect = prev ?? 0;
    if (e.before !== expect)
      throw new DataError(
        `数据一致性核对失败：商品 ${e.product} 仓库 ${e.wh} 第 #${e.seq} 条流水（单据 ${e.doc}）` +
        `变动前余量 ${e.before} 与此前末笔余量 ${expect} 不连续，拒绝输出报表（不自动修复）`,
      );
    (lastAfter[e.product] ??= nullProto<Record<string, number>>())[e.wh] = e.after;
  }
  // 末笔余量与当前实存一致（双向：流水出现的组合与实存出现的组合都要核对）
  const combos = new Set<string>();
  for (const pid of Object.keys(lastAfter)) for (const wh of Object.keys(lastAfter[pid])) combos.add(`${pid}\0${wh}`);
  for (const pid of Object.keys(store.stock)) for (const wh of Object.keys(store.stock[pid])) combos.add(`${pid}\0${wh}`);
  for (const key of combos) {
    const [pid, wh] = key.split('\0');
    const replayed = lastAfter[pid]?.[wh] ?? 0;
    const actual = getStock(store.stock, pid, wh);
    if (replayed !== actual)
      throw new DataError(
        `数据一致性核对失败：商品 ${pid} 仓库 ${wh} 流水末笔余量 ${replayed} 与当前实存 ${actual} 不一致，拒绝输出报表（不自动修复）`,
