interface Boundary { id: string; first: number; last: number; }

function resolveBoundary(store: Store, label: string, id: string, docFirst: ..., docLast: ...): Boundary {
  const first = docFirst[id];
  if (first !== undefined) return { id, first, last: docLast[id] };
  if (store.purchases[id] !== undefined)
    throw new BizError(`${label}单据 ${id} 是采购单：采购登记不产生库存流水，不能用作期间边界`);
  if (store.cancels[id] !== undefined)
    throw new BizError(`${label}单据 ${id} 是取消单：取消不产生库存流水，不能用作期间边界`);
  const rev = store.reversals[id];
  if (rev !== undefined)
    throw new BizError(`${label}单据 ${id} 是冲销取消单 ${rev.orig} 的冲销单：不产生库存流水，不能用作期间边界`);
  throw new BizError(`${label}单据 ${id} 不存在或没有库存流水，不能用作期间边界`);
}
