    throw new BizError(`${label}单据 ${id} 不存在或没有库存流水，不能用作期间边界`);
  };
  const fromB = fromId === undefined ? undefined : resolveBoundary('起点', fromId);
  const toB = toId === undefined ? undefined : resolveBoundary('终点', toId);
