    throw new BizError(`起点单据 ${fromId} 的首次提交顺序晚于终点单据 ${toId}，拒绝出报表`);
  const fromEnd = fromB?.last ?? 0; // 期间不含起点：自起点单据全部流水完成后开始
  const endSeq = toB?.last ?? Number.MAX_SAFE_INTEGER; // 终点包含该单全部流水；缺省截至当前
